\n     const title = parts[0].replace(''['', '''').replace('']'', '''').replaceAll(''*'', '''');\n     htmlCaption += `<b>${title.replaceAll(''\\n'', '''')}</b>\\n\\n`;\n\n     // 2. Аннотация (убираем маркер 📖, если он в начале)\n     const annotation = parts[1].replace(''📖'', '''').trim();\n     htmlCaption += `${annotation}\\n\\n`;\n\n     // 3. Хештеги\n     const hashtags = parts[2];\n     htmlCaption += `<code>${hashtags}</code>`;\n\n     // htmlCaption = htmlCaption.replaceAll(''\\n'', '''');\n } else {\n     // Если формат нарушен, просто упаковываем как есть\n     htmlCaption = rawText.replaceAll(/\\n/g, ''<br>'');\n }\n\n // ПРОВЕРКА ЛИМИТА TELEGRAM (1024 символа для фото)\n const TG_LIMIT = 1024;\n if (htmlCaption.length > TG_LIMIT) {\n     htmlCaption = htmlCaption.substring(0, TG_LIMIT - 3) + \"...\";\n }\n\n return {\n     html_text: htmlCaption\n };"}, "typeVersion": 2}, {"id": "b08f1aef-f23a-4025-a5fd-6296e6bd8ff4", "name": "Billing Polza.ai", "type": "n8n-nodes-base.httpRequest", "onError": "continueRegularOutput", "position": [-1088, 160], "parameters": {"url": "https://polza.ai/api/v1/balance", "options": {"timeout": 10000}, "sendHeaders": true, "authentication": "genericCredentialType", "genericAuthType": "httpHeaderAuth", "headerParameters": {"parameters": []}}, "credentials": {"httpHeaderAuth": {"id": "3dfmGKUa1Q01H200", "name": "Billing Polza Header"}}, "retryOnFail": true, "typeVersion": 4.4, "alwaysOutputData": true}, {"id": "ac36cd4a-84d4-43d7-909e-3908f96dd91f", "name": "Billing Neuro", "type": "n8n-nodes-base.httpRequest", "onError": "continueRegularOutput", "disabled": true, "position": [-880, 160], "parameters": {"url": "https://neuroapi.host/v1/dashboard/billing/usage", "options": {"timeout": 10000}, "sendHeaders": true, "authentication": "genericCredentialType", "genericAuthType": "httpHeaderAuth", "headerParameters": {"parameters": []}}, "credentials": {"httpHeaderAuth": {"id": "GIoKsxpIObYHo6Nm", "name": "Billing Neuro Header"}}, "r