essage_id","required":false,"defaultMatch":false,"display":true,"type":"number","readOnly":false,"removed":true},{"id":"chat_id","displayName":"chat_id","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"glossary_make","displayName":"glossary_make","required":false,"defaultMatch":false,"display":true,"type":"boolean","readOnly":false,"removed":false},{"id":"message_start","displayName":"message_start","required":false,"defaultMatch":false,"display":true,"type":"number","readOnly":false,"removed":true},{"id":"message_process","displayName":"message_process","required":false,"defaultMatch":false,"display":true,"type":"number","readOnly":false,"removed":true},{"id":"PostProdaction","displayName":"PostProdaction","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.dataTable","typeVersion":1.1,"position":[-1040,224],"id":"68b849c8-d34e-4392-8784-2d5983f2c547","name":"Insert row","alwaysOutputData":true,"executeOnce":true},{"parameters":{"resource":"table","operation":"delete","dataTableId":{"__rl":true,"value":"select_files","mode":"name"}},"type":"n8n-nodes-base.dataTable","typeVersion":1.1,"position":[-1344,224],"id":"caf27354-6344-4a16-a805-cb5b6036d51a","name":"Delete a data table","executeOnce":true,"onError":"continueRegularOutput"},{"parameters":{"operation":"executeQuery","query":"-- Таблица summary арок\nDROP TABLE IF EXISTS document_files CASCADE;\nCREATE TABLE IF NOT EXISTS document_files (\n  id SERIAL PRIMARY KEY,\n  translate_file bytea,\n  translate_file_data json,\n  glossary bytea,\n  glossary_data json,\n  prompt bytea,\n  prompt_data json,\n  post_prod bytea,\n  post_prod_data json,\n  source text\n);\nINSERT INTO document_files (source) VALUES (''telegram'');","options":{}},"type":"n8n-nodes-base.postgres","typeVersion":2.6,"position":[-880,224],"id":"9a2f0c1d-a0ac-4aed-8453-73a9b63ccccc","name":"Init document_files","credentials":{"postgres":{"id":"iGih4QSBWfmpkdGY","name":"Postgres account"}}}]', '{"Get base64 string":{"main":[[{"node":"Запись файла для перевода в БД","type":"main","index":0}]]},"Запись файла для перевода в БД":{"main":[[{"node":"Merge2","type":"main","index":0}]]},"Get translate file":{"main":[[{"node":"Get base64 string","type":"main","index":0}]]},"Get base64 string1":{"main":[[{"node":"Запись глоссария в БД","type":"main","index":0}]]},"Get base64 string2":{"main":[[{"node":"Запись промта в БД","type":"main","index":0}]]},"Get glossary":{"main":[[{"node":"Get base64 string1","type":"main","index":0}]]},"Get prompt":{"main":[[{"node":"Get base64 string2","type":"main","index":0}]]},"Запись промта в БД":{"main":[[{"node":"Merge2","type":"main","index":3}]]},"Запись глоссария в БД":{"main":[[{"node":"Merge2","type":"main","index":1}]]},"Промт задан?":{"main":[[{"node":"Get prompt","type":"main","index":0}],[{"node":"Merge2","type":"main","index":2}]]},"Merge2":{"main":[[{"node":"Edit Fields","type":"main","index":0}]]},"Edit Fields":{"main":[[{"node":"Старт перевода","type":"main","index":0}]]},"Глоссарий задан?":{"main":[[{"node":"Get glossary","type":"main","index":0}],[{"node":"Merge2","type":"main","index":4}]]},"Сообщение о создании задачи":{"main":[[{"node":"Глоссарий задан?","type":"main","index":0},{"node":"Промт задан?","type":"main","index":0},{"node":"Промт для постредакта задан?","type":"main","index":0},{"node":"Get translate file","type":"main","index":0}]]},"Get base64 string3":{"main":[[{"node":"Запись промта в БД1","type":"main","index":0}]]},"Запись промта в БД1":{"main":[[{"node":"Merge2","type":"main","index":5}]]},"Промт для постредакта задан?":{"main":[[{"node":"Get prompt postProd","type":"main","index":0}],[{"node":"Merge2","type":"main","index":5}]]},"Get prompt postProd":{"main":[[{"node":"Get base64 string3","type":"main","index":0}]]},"Start Workflow":{"main":[[{"node":"Delete a data table","type":"main","index":0}]]},"Create a data table":{"main":[[{"node":"Insert row","type":"main","index":0}]]},"Delete a data table":{"main":[[{"node":"Create a data table","type":"main","index":0}]]},"Insert row":{"main":[[{"node":"Init document_files","type":"main","index":0}]]},"Init document_files":{"main":[[{"node":"Сообщение о создании задачи","type":"main","index":0}]]}}', '2026-04-08 08:43:24.177+00', '2026-04-28 18:44:37.865+00', '{"binaryMode":"separate","executionOrder":"v1","saveFailedExecution":"all","saveManualExecutions":true,"saveExecutionProgress":"none","saveDataSuccessExecution":"all","timeSavedMode":"fixed","callerPolicy":"workflowsFromSameOwner","availableInMCP":false}', NULL, '{"Start Workflow":[{"json":{"file_name":"ЗлойДух.docx","file_id":"BQACAgIAAxkBAAISQGnuVYZP5YxmH3lsAU-P94stFvoyAAIFnwAC_p5xS99X0BXaOCAhOwQ","glossary_file_name":"Glossary ЗлойДух.xlsx","glossary_id":"BQACAgIAAxkBAAISNmnuRprI1jkzYzFjhp2RQMIvJJDeAAI2ngAC_p5xS-JYTk61EO0rOwQ","create_glossary":false,"bp_file_name":"Промт для Злой Дух.docx","bp_file_id":"BQACAgIAAxkBAAINrmnSUgFP3qAi9hRGR29up0LU9LM3AAJ5nQACTS2QStUeIATJHNyEOwQ","pp_file_name":"","pp_file_id":"","chat_id":"923741104"}}]}', '208a56db-6ec9-4c4c-8885-1beaf179bd7d', 0, 'rlk5lgq3uE4N0yl0', '{"templateCredsSetupCompleted":true}', 'SElvD1cNXKPyfAJi', false, 209, NULL, '208a56db-6ec9-4c4c-8885-1beaf179bd7d');
INSERT INTO public.workflow_entity VALUES ('Sub-Workflow: Gemini HTTP Proxy', false, '[{"name": "Execute Workflow Trigger", "type": "n8n-nodes-base.executeWorkflowTrigger", "position": [0, 0], "parameters": {}, "typeVersion": 1}, {"name": "Prepare Payload", "type": "n8n-nodes-base.code", "position": [220, 0], "parameters": {"jsCode": "const input = $input.first().json;\nconst apiKey = input.apiKey;\nconst prompt = input.prompt;\nconst model = input.model || ''gemini-1.5-flash'';\nconst temperature = input.temperature !== undefined ? input.temperature : 0.7;\nconst systemInstruction = input.system_instruction;\nconst history = input.history;\n\nif (!apiKey) throw new Error(\"API Key is missing.\");\n\nlet contents = [];\nif (history && Array.isArray(history) && history.length > 0) {\n    contents = history;\n} else {\n    contents = [{ \"role\": \"user\", \"parts\": [{ \"text\": prompt }] }];\n}\n\nconst body = { contents: contents, generationConfig: { temperature: temperature } };\nif (systemInstruction) { body.system_instruction = { parts: [{ \"text\": systemInstruction }] }; }\n\nreturn { url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`, body: body };"}, "typeVersion": 2}, {"name": "Call Gemini API", "type": "n8n-nodes-base.httpRequest", "position": [440, 0], "parameters": {"url": "={{ $json.url }}", "method": "POST", "options": {"maxTries": 5, "retryOnFail": true, "waitBetweenTries": 5000}, "jsonBody": "={{ $json.body }}", "sendBody": true, "specifyBody": "json"}, "typeVersion": 4.1}, {"name": "Extract Response", "type": "n8n-nodes-base.code", "position": [660, 0], "parameters": {"jsCode": "const data = $input.first().json;\nlet resultText = \"\";\ntry { resultText = data.candidates[0].content.parts[0].text; } catch(e) { resultText = \"Error or safety block.\"; }\nreturn { response: resultText, raw: data };"}, "typeVersion": 2}]', '{"Call Gemini API": {"main": [[{"node": "Extract Response", "type": "main", "index": 0}]]}, "Prepare Payload": {"main": [[{"node": "Call Gemini API", "type": "main", "index": 0}]]}, "Execute Workflow Trigger": {"main": [[{"node": "Prepare Payload", "type": "main", "index": 0}]]}}', '2026-04-25 09:45:58.029+00', '2026-04-25 09:45:58.029+00', '{"executionOrder": "v1"}', NULL, NULL, '48cc3efa-3c96-4ca1-9a75-e8e9201f5a44', 0, 'vi4XdN3PCqbqu8NK', NULL, NULL, false, 1, NULL, NULL);
INSERT INTO public.workflow_entity VALUES ('Sub-Workflow: Gemini HTTP Proxy', false, '[{"parameters":{},"type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1,"position":[0,0],"id":"e2ba34e3-1111-4444-8888-abcdef123456","name":"Execute Workflow Trigger"},{"parameters":{"jsCode":"const input = $input.first().json;\nconst apiKey = input.apiKey;\nconst prompt = input.prompt;\nconst model = input.model || ''gemini-2.5-flash'';\nconst temperature = input.temperature !== undefined ? input.temperature : 0.7;\nconst systemInstruction = input.system_instruction;\nconst history = input.history;\n\nif (!apiKey) throw new Error(\"API Key is missing.\");\n\nlet contents = [];\nif (history && Array.isArray(history) && history.length > 0) {\n    contents = history;\n} else {\n    contents = [{ \"role\": \"user\", \"parts\": [{ \"text\": prompt }] }];\n}\n\nconst body = { contents: contents, generationConfig: { temperature: temperature } };\nif (systemInstruction) { body.system_instruction = { parts: [{ \"text\": systemInstruction }] }; }\n\nreturn { url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`, body: body };"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[224,0],"id":"11111111-2222-3333-4444-555555555555","name":"Prepare Payload"},{"parameters":{"method":"POST","url":"={{ $json.url }}","sendBody":true,"specifyBody":"json","jsonBody":"={{ $json.body }}","options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[448,0],"id":"22222222-3333-4444-5555-666666666666","name":"Call Gemini API"},{"parameters":{"jsCode":"const data = $input.first().json;\nlet resultText = \"\";\ntry { resultText = data.candidates[0].content.parts[0].text; } catch(e) { resultText = \"Error or safety block.\"; }\nreturn { response: resultText, raw: data };"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[672,0],"id":"33333333-4444-5555-6666-777777777777","name":"Extract Response"}]', '{"Execute Workflow Trigger":{"main":[[{"node":"Prepare Payload","type":"main","index":0}]]},"Prepare Payload":{"main":[[{"node":"Call Gemini API","type":"main","index":0}]]},"Call Gemini API":{"main":[[{"node":"Extract Response","type":"main","index":0}]]}}', '2026-04-25 09:48:24.376+00', '2026-04-26 13:44:29.153+00', '{"executionOrder":"v1","binaryMode":"separate"}', NULL, '{}', '6bc7db77-5229-4674-ae95-2ab81cc37bd7', 0, 'UmCkmK4Xhtgn1zUI', NULL, NULL, true, 3, NULL, NULL);
INSERT INTO public.workflow_entity VALUES ('Постредактура', true, '[{"id": "772d9b32-ddd1-4d7d-ac85-8800104dcce8", "name": "Start Workflow", "type": "n8n-nodes-base.executeWorkflowTrigger", "position": [-640, 0], "parameters": {"workflowInputs": {"values": [{"name": "ko_text"}, {"name": "ru_text"}, {"name": "glossary"}, {"name": "rag"}]}}, "typeVersion": 1.1}, {"id": "ffb76207-f6b1-4414-830e-b84268dc96d0", "name": "Формирование промтов для перевода", "type": "n8n-nodes-base.code", "position": [-304, 0], "parameters": {"jsCode": "let UserPrompt = '''';\nlet SystemPrompt = '''';\n\n// User prompt\nUserPrompt += `Ниже представлены два варианта текста для работы. Твоя цель — улучшить ЧЕРНОВОЙ ПЕРЕВОД, опираясь на ОРИГИНАЛ.\n\n### ОРИГИНАЛ (КОРЕЙСКИЙ):\n---\n${$(''Start Workflow'').first().json.ko_text}\n---\n\n### ЧЕРНОВОЙ ПЕРЕВОД (РУССКИЙ):\n---\n${$(''Start Workflow'').first().json.ru_text}\n---\n\n### ДОПОЛНИТЕЛЬНЫЕ УКАЗАНИЯ ДЛЯ ЭТОГО ОТРЕЗКА:\n1. Сверься с Глоссарием и RAG-справкой из системного промпта.\n2. Особое внимание удели передаче атмосферы и точности буддийских терминов.\n3. Проверь, чтобы все местоимения (он/она) соответствовали полу персонажей.\n\nПожалуйста, выдай финальный литературный текст.\n`;\n\n//System Prompt\nSystemPrompt += $(''Чтение промтов'').all().find(item => item.json.name === ''PP Default'')?.json?.prompt || '''';\n\nlet glossary_text = $(''Start Workflow'').first().json.glossary || '''';\nSystemPrompt = SystemPrompt.replace(''{{GLOSSARY}}'', glossary_text)\n\nlet light_rag = '''';\nif (!$(''Start Workflow'').first().json.rag.includes(''[no-context]'')) {\n  light_rag = `\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\nБАЗА ЗНАНИЙ — данные из RAG\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\n${$(''Start Workflow'').first().json.rag}\n  `;\n}\nSystemPrompt = SystemPrompt.replace(''{{LIGHT_RAG}}'', light_rag)\n\nreturn { UserPrompt, SystemPrompt };\n"}, "typeVersion": 2}, {"id": "cf2dd9b8-641e-4fb4-995d-7e15bad681c8", "name": "Чтение промтов", "type": "n8n-nodes-base.postgres", "position": [-480, 0], "parameters": {"table": {"__rl": true, "mode": "list", "value": "translate_prompts", "cachedResultName": "translate_prompts"}, "schema": {"__rl": true, "mode": "list", "value": "public"}, "options": {}, "operation": "select", "returnAll": true}, "credentials": {"postgres": {"id": "iGih4QSBWfmpkdGY", "name": "Postgres account"}}, "executeOnce": true, "retryOnFail": true, "typeVersion": 2.6, "alwaysOutputData": true}, {"id": "2658312b-c8dc-4b79-984b-143a40476855", "name": "text_validator", "type": "@n8n/n8n-nodes-langchain.toolCode", "position": [128, 256], "parameters": {"jsCode": "// Скрипт для n8n Custom Code Tool (v2.12+)\n// Доступ к данным через переменную \"query\"\nconsole.log(query )\nconst text = query; \nlet issues = [];\n\n// 1. Проверка на корейские иероглифы\nconst koreanRegex = /[\\uac00-\\ud7af\\u1100-\\u11ff\\u3130-\\u318f\\ua960-\\ua97f\\ud7b0-\\ud7ff]/g;\nconst koreanMatches = text.match(koreanRegex);\nif (koreanMatches) {\n    issues.push(`Корейские символы: ${koreanMatches.length} шт.`);\n}\n\n// 2. Проверка на английские буквы\nconst englishRegex = /[a-zA-Z]/g;\nconst englishMatches = text.match(englishRegex);\nif (englishMatches) {\n    issues.push(`Английские буквы: ${englishMatches.length} шт.`);\n}\n\n// 3. Проверка на тире в середине предложений\nconst lines = text.split(''\\n'');\nlines.forEach((line, index) => {\n    const trimmed = line.trim();\n    if (trimmed.length > 1 && trimmed.slice(1).match(/[—–-]/)) {\n        issues.push(`Линия ${index + 1}: запрещенное тире.`);\n    }\n});\n\nif (issues.length === 0) {\n    return \"ВЕРДИКТ: OK. Техническая проверка пройдена.\";\n} else {\n    return \"ВЕРДИКТ: ОШИБКА! \" + issues.join(\" | \") + \". Исправь текст.\";\n}", "description": "Обязательный инструмент для проверки итогового текста. Ищет корейские и английские символы, а также запрещенные тире в середине предложений. Возвращает ошибки или \"OK\".\n"}, "typeVersion": 1.3}, {"id": "a8fef615-2f04-4fa7-934a-027d9b278bdf", "name": "parentheses_checker", "type": "@n8n/n8n-nodes-langchain.toolCode", "position": [304, 256], "parameters": {"jsCode": "// Скрипт для n8n Custom Code Tool (v2.12+)\n// Доступ к данным через переменную \"query\"\n\nconst inputStr = query;\nconst parts = inputStr.split(''|'');\nif (parts.length < 2) {\n    return \"ОШИБКА ФОРМАТА: Используй ''Термин1, Термин2 | Весь текст''\";\n}\n\nconst terms = parts[0].split('','').map(t => t.trim());\nconst text = parts[1];\nlet missing = [];\n\nterms.forEach(term => {\n    if (!term) return;\n    const escapedTerm = term.replace(/[.*+?^${}()|[\\]\\\\]/g, ''\\\\$&'');\n    const pattern = new RegExp(`${escapedTerm}\\\\s*\\\\([^)]+\\\\)`, ''i'');\n    if (!pattern.test(text)) {\n        missing.push(term);\n    }\n});\n\nif (missing.length === 0) {\n    return \"ВЕРДИКТ: OK. Все пояснения найдены.\";\n} else {\n    return \"ВЕРДИКТ: ОШИБКА! Добавь пояснения в скобках для: \" + missing.join('', '');\n}", "description": "Проверяет, что для терминов из глоссария добавлены пояснения в скобках. Формат ввода: ''Термин1, Термин2 | Текст''. Сообщает, если скобки пропущены."}, "typeVersion": 1.3}, {"id": "1e6e528c-9e64-4c1f-97b9-468b9d57908e", "name": "check_forbidden_words", "type": "n8n-nodes-base.postgresTool", "position": [496, 256], "parameters": {"query": "SELECT bad_word, replacement \nFROM style_replacements \nWHERE $1 ILIKE ''%'' || bad_word || ''%'';\n", "options": {"queryReplacement": "={{ $fromAI(\"input\") }}"}, "operation": "executeQuery", "descriptionType": "manual", "toolDescription": "Инструмент для поиска стилистически запрещенных слов (например: опёрся, тогдашний, мол, является). Проверяет текст по базе данных и выдает рекомендации по замене на литературные синонимы. На вход принимает весь текст.\n"}, "credentials": {"postgres": {"id": "iGih4QSBWfmpkdGY", "name": "Postgres account"}}, "typeVersion": 2.6}, {"id": "5eda1bf6-9552-4c96-b93c-e7c77f835dc0", "name": "GPT-5.2 from Polza", "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi", "position": [-208, 256], "parameters": {"model": {"__rl": true, "mode": "list", "value": "openai/gpt-5.2-chat", "cachedResultName": "openai/gpt-5.2-chat"}, "options": {}, "builtInTools": {}}, "credentials": {"openAiApi": {"id": "oyDHju4LEcPX94u4", "name": "polza.ai"}}, "typeVersion": 1.3}, {"id": "72c34264-d8ac-41f3-a001-665ce2beb717", "name": "Gemini 2.5 Flash (Test)", "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi", "position": [-32, 256], "parameters": {"model": {"__rl": true, "mode": "list", "value": "google/gemini-3.1-flash-lite", "cachedResultName": "google/gemini-3.1-flash-lite"}, "options": {}, "builtInTools": {}}, "credentials": {"openAiApi": {"id": "dw2ygQ53RyVkCAva", "name": "Polza"}}, "typeVersion": 1.3}, {"id": "0c57125a-e633-4ce7-a24a-49c5d5b5b664", "name": "Translate Chunk", "type": "@n8n/n8n-nodes-langchain.agent", "onError": "continueErrorOutput", "position": [-128, 0], "parameters": {"text": "={{ $json.UserPrompt }}\n", "options": {"systemMessage": "={{ $json.SystemPrompt }}"}, "promptType": "define", "needsFallback": true}, "retryOnFail": true, "typeVersion": 3.1}]', '{"Start Workflow":{"main":[[{"node":"Чтение промтов","type":"main","index":0}]]},"Формирование промтов для перевода":{"main":[[{"node":"Translate Chunk","type":"main","index":0}]]},"Чтение промтов":{"main":[[{"node":"Формирование промтов для перевода","type":"main","index":0}]]},"text_validator":{"ai_tool":[[{"node":"Translate Chunk","type":"ai_tool","index":0}]]},"parentheses_checker":{"ai_tool":[[{"node":"Translate Chunk","type":"ai_tool","index":0}]]},"check_forbidden_words":{"ai_tool":[[{"node":"Translate Chunk","type":"ai_tool","index":0}]]},"GPT-5.2 from Polza":{"ai_languageModel":[[{"node":"Translate Chunk","type":"ai_languageModel","index":0}]]},"Gemini 2.5 Flash (Test)":{"ai_languageModel":[[{"node":"Translate Chunk","type":"ai_languageModel","index":1}]]}}', '2026-04-04 18:08:57.765+00', '2026-04-27 18:32:02.567+00', '{"binaryMode":"separate","callerPolicy":"workflowsFromSameOwner","timeSavedMode":"fixed","availableInMCP":false,"executionOrder":"v1","saveFailedExecution":"all","saveManualExecutions":true,"saveExecutionProgress":"none","saveDataErrorExecution":"all","saveDataSuccessExecution":"none"}', NULL, '{"Start Workflow":[{"json":{"ko_text":"04.\n\n\"두루 빛을 비추시는 존재를 생각하며....\"\n\n총본산 대법 당에서는 특별 법회가 한창이었다.\n\n\"안으로는 진여법계를 비추고, 밖으로는 모든 중생에게 법성을 비추어....\"\n\n신주는 대종사의 발원문 소리를 한 귀로 듣고 흘리며, 지난 일을 회상했다.\n\n아버지에 대한 가장 오래된 기억은, 제게 절을 하던 모습이었다.\n\n법당 측면의 제일 끝에 선 그는 비스듬한 대각선 방향, 대종사가 선 단상을 응시했다.\n\n전대 중부지회주 우국헌은 바로 저 앞에서 어린 그에게 무릎을 꿇었다.\n\n바즈라닥시나이시자, 바즈라바마이시자, 광명의 화신이시여....\n\n\".......\"\n\n마음이 차분하게 가라앉았다.\n\n그러고 보면, 이런 시간을 갖는 것도 오랜만이었다.\n\n교구의 소속일 뿐, 종과는 거리를 두는 그는 공식 석상에 거의 불참석했다. 종 또한 예언의 아이를 최대한 감 추는 방식으로 굴러갔다. 그건 예전부터 그를 통해 여러 일을 도모하고자 했던 원로회와 그의 의견이 단번에 일치한 유일한 사안이었다.\n\n특히 초하루법회, 일요법회 등 일반 교구의 신도들이 참석하는 자리에서는 그의 존재를 철저히 배제했다. 그 가 참석하는 법회라곤 지금처럼 종사들과 일부 승려들이 모여 치르는 특별 법회가 전부였다.\n\n","ru_text":"04.\n\n— Помышляя о сущем, что озаряет повсюду светом....\n\nВ Великом зале Дхармы главного монастыря ордена как раз шла специальная служба.\n\n— Внутри озаряя мир истинной таковости (абсолютную реальность), вовне озаряя природу Дхармы (истинную сущность закона) всем живым существам....\n\nСинджу слушал одним ухом и пропускал мимо ушей голос Великого патриарха, читающего текст обета, вспоминая прошлое.\n\nСамое раннее воспоминание об отце — это его фигура, кланяющаяся ему.\n\nСтоя в самом конце боковой стороны зала Дхармы, он смотрел по косой диагонали на возвышение, где стоял Великий патриарх.\n\nПредыдущий глава центрального отделения Угукхон прямо там, впереди, опустился перед ним, ещё ребёнком, на колени.\n\nВаджра-дакшинайши, Ваджра-вамайши, о воплощение света....\n\n— .......\n\nСердце спокойно осело.\n\nЕсли подумать, такие мгновения выпадали ему нечасто.\n\nОн лишь числился при епархии, но держался в стороне от ордена и почти не появлялся на официальных мероприятиях. Сам орден также действовал так, чтобы по возможности скрывать ребёнка пророчества. Это был единственный вопрос, в котором его мнение и мнение совета старейшин, издавна пытавшихся через него осуществить разные замыслы, совпали сразу.\n\nОсобенно на службах первого дня месяца, на воскресных службах и прочих собраниях, где присутствовали обычные верующие епархии, его существование тщательно исключали. Единственные службы, на которых он присутствовал, были лишь такие специальные службы, как нынешняя, где собирались наставники ордена и некоторые монахи.","glossary":"━━━━━━━━━━━━━━━━━━━━━━━━━━━\nГЛОССАРИЙ — ИСТОЧНИК ИСТИНЫ\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\n우신주 = У Синджу (gender: male).\n허정윤 = Хо Чонюн (gender: male).\n고봉춘 = Ко Бончун (gender: male).\n김도우 = Ким Доу.\n기녹연 = Ки Нокён.\n사천왕문 = ворота Четырёх небесных царей.\n도련님 = молодой господин.\n영안 = духовное зрение.\n귀신 = дух.\n만월당 = зал полной луны.\n무당 = шаманка.\n박수 = шаман паксу.\n만신 = великая шаманка.\n범아종 = Бомаджон (gender: male).","rag":"- Дачон: мужской, он является основным персонажем и представляет собой духовное существо, отражающее мудрость и сострадание.\n- Укок Хон: мужской, участвует в обрядах и является соперником Дачона в некоторых аспектах, проявляя стремление к знаний и самосовершенствованию.\n- Храм: место, где проходят особые церемонии, такая как специальная служба, отражающая духовную практику и взаимодействие между персонажами."}}]}', '5a07cb3a-4bd9-4f00-8a54-547cafaea25e', 0, 'A8zKJVQgROH1cnkv', '{"templateCredsSetupCompleted":true}', 'G9OqDfBu0fq5UT12', false, 324, NULL, '5a07cb3a-4bd9-4f00-8a54-547cafaea25e');
INSERT INTO public.workflow_entity VALUES ('MOEX | Bootstrap Storage', false, '[{"id":"manual-trigger","name":"Manual Trigger","type":"n8n-nodes-base.manualTrigger","typeVersion":1,"position":[260,300],"parameters":{}},{"id":"init-postgres","name":"Init Postgres Schema","type":"n8n-nodes-base.postgres","typeVersion":2.6,"position":[560,300],"parameters":{"resource":"database","operation":"executeQuery","query":"CREATE TABLE IF NOT EXISTS moex_watchlist (\n  secid text PRIMARY KEY,\n  board text NOT NULL DEFAULT ''TQBR'',\n  market text NOT NULL DEFAULT ''shares'',\n  instrument_group text NOT NULL DEFAULT ''stocks'',\n  issuer_name text,\n  news_keywords text,\n  active boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS moex_market_snapshot (\n  id bigserial PRIMARY KEY,\n  collected_at timestamptz NOT NULL DEFAULT now(),\n  secid text NOT NULL,\n  board text NOT NULL,\n  market text NOT NULL,\n  instrument_group text NOT NULL,\n  interval_code integer NOT NULL,\n  interval_name text NOT NULL,\n  from_date date,\n  till_date date,\n  candles_count integer NOT NULL DEFAULT 0,\n  latest_open numeric,\n  latest_close numeric,\n  latest_high numeric,\n  latest_low numeric,\n  latest_volume numeric,\n  change_pct numeric,\n  payload jsonb NOT NULL,\n  summary_text text,\n  source text NOT NULL DEFAULT ''moex_iss''\n);\n\nCREATE INDEX IF NOT EXISTS idx_moex_market_snapshot_secid_collected\n  ON moex_market_snapshot (secid, collected_at DESC);\nCREATE INDEX IF NOT EXISTS idx_moex_market_snapshot_interval\n  ON moex_market_snapshot (interval_name, collected_at DESC);\n\nCREATE TABLE IF NOT EXISTS moex_news_item (\n  id bigserial PRIMARY KEY,\n  collected_at timestamptz NOT NULL DEFAULT now(),\n  source text NOT NULL,\n  feed_url text,\n  external_id text NOT NULL,\n  published_at timestamptz,\n  title text NOT NULL,\n  link text,\n  summary text,\n  matched_secid text,\n  matched_keywords text,\n  payload jsonb NOT NULL,\n  UNIQUE (source, external_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_moex_news_item_secid_published\n  ON moex_news_item (matched_secid, published_at DESC);\n\nCREATE TABLE IF NOT EXISTS moex_analysis_report (\n  id bigserial PRIMARY KEY,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  secid text,\n  instrument_group text,\n  report_type text NOT NULL,\n  model_name text,\n  summary_text text NOT NULL,\n  payload jsonb NOT NULL,\n  knowledge_source text\n);\n\nCREATE INDEX IF NOT EXISTS idx_moex_analysis_report_secid_created\n  ON moex_analysis_report (secid, created_at DESC);\n\nINSERT INTO moex_watchlist (secid, board, market, instrument_group, issuer_name, news_keywords, active)\nVALUES\n  (''SBER'', ''TQBR'', ''shares'', ''stocks'', ''Сбербанк'', ''сбер, сбербанк, sber'', true),\n  (''GAZP'', ''TQBR'', ''shares'', ''stocks'', ''Газпром'', ''газпром, gazprom, gazp'', true),\n  (''LKOH'', ''TQBR'', ''shares'', ''stocks'', ''Лукойл'', ''лукойл, lukoil, lkoh'', true)\nON CONFLICT (secid) DO UPDATE SET\n  board = EXCLUDED.board,\n  market = EXCLUDED.market,\n  instrument_group = EXCLUDED.instrument_group,\n  issuer_name = EXCLUDED.issuer_name,\n  news_keywords = EXCLUDED.news_keywords,\n  active = EXCLUDED.active,\n  updated_at = now();","options":{"queryBatching":"single"}},"credentials":{"postgres":{"id":"iGih4QSBWfmpkdGY","name":"Postgres account"}}},{"id":"bootstrap-webhook","name":"Bootstrap Webhook","type":"n8n-nodes-base.webhook","typeVersion":2.1,"position":[260,460],"parameters":{"httpMethod":"POST","path":"moex-bootstrap-storage","responseMode":"lastNode","responseData":"firstEntryJson"},"webhookId":"6b8307bb-39b2-4c65-b0ae-a5f5ce00e1bc"}]', '{"Manual Trigger":{"main":[[{"node":"Init Postgres Schema","type":"main","index":0}]]},"Bootstrap Webhook":{"main":[[{"node":"Init Postgres Schema","type":"main","index":0}]]}}', '2026-04-17 17:01:46.361+00', '2026-04-17 19:01:22.093+00', '{"executionOrder":"v1","saveDataErrorExecution":"all","saveDataSuccessExecution":"none","saveManualExecutions":true,"saveExecutionProgress":true,"callerPolicy":"workflowsFromSameOwner","availableInMCP":false}', NULL, NULL, 'eee70f71-b45c-47ac-927b-4c63a923bc89', 1, 'j21mYQWh2XSPv0l2', NULL, 'FCsqLrchKiASqWpN', false, 10, NULL, NULL);
