INSERT INTO public.workflow_entity VALUES ('[Send] processing', true, '[{"id": "5ccb8d3f-76d1-4feb-9a98-4af48e4ce545", "name": "Данные document_jobs", "type": "n8n-nodes-base.postgres", "position": [-256, 320], "parameters": {"query": "SELECT * FROM document_jobs a, job_current b WHERE a.id =b.job_id;", "options": {}, "operation": "executeQuery"}, "credentials": {"postgres": {"id": "iGih4QSBWfmpkdGY", "name": "Postgres account"}}, "executeOnce": true, "retryOnFail": true, "typeVersion": 2.6, "alwaysOutputData": true}, {"id": "27e4020f-e471-4a28-b2df-bed8bcaaec19", "name": "Общее количество чанков", "type": "n8n-nodes-base.postgres", "position": [-64, 320], "parameters": {"query": "SELECT count(*) as chunks_total FROM document_chunks WHERE job_id IN (SELECT job_id FROM job_current);", "options": {}, "operation": "executeQuery"}, "credentials": {"postgres": {"id": "iGih4QSBWfmpkdGY", "name": "Postgres account"}}, "executeOnce": true, "retryOnFail": true, "typeVersion": 2.6, "alwaysOutputData": true}, {"id": "9e5273ce-b1ba-41f1-a450-9dd693617f32", "name": "Количество законченных чанков", "type": "n8n-nodes-base.postgres", "position": [128, 320], "parameters": {"query": "SELECT count(*) as chunks_done FROM document_chunks WHERE job_id IN (SELECT job_id FROM job_current) AND status=''done'';", "options": {}, "operation": "executeQuery"}, "credentials": {"postgres": {"id": "iGih4QSBWfmpkdGY", "name": "Postgres account"}}, "executeOnce": true, "retryOnFail": true, "typeVersion": 2.6, "alwaysOutputData": true}, {"id": "542a645e-aabd-463d-b0fa-7da72fd96312", "name": "Сообщение Перевод в процессе", "type": "n8n-nodes-base.code", "position": [-752, 640], "parameters": {"jsCode": "const RUBLE_EXCHANGE_RATE = 79;\n\nconst billing_polza = Number($(''Данные document_jobs'').first().json.billing_polza) - Number($(''Billing Polza.ai'').first().json.amount);\nconst billing_neuro = -(Number($(''Данные document_jobs'').first().json.billing_neuro) - Number($(''Billing Neuro'').first().json.total_usage)) / 100;\n\nconst startedAtMs = DateTime.fromISO($(''Данные document_jobs'').first().json.created_at);\nconst diff = startedAtMs.diffNow().negate().toFormat(\"hh'':''mm'':''ss\")\n\nconst done = Number($(''Количество законченных чанков'').first().json.chunks_done);\nconst total = Number($(''Общее количество чанков'').first().json.chunks_total);\n// const done = Math.floor(Math.random() * total);\nconst ratio = Math.min(1, Math.max(0, done / total));\n\nconst startedAt = startedAtMs.toFormat(\"dd.MM.yyyy HH:mm:ss\");\n\nconst width =20;\nconst filled = Math.round(ratio * width);\nconst bar = ''█''.repeat(filled) + ''░''.repeat(width - filled);\n\nreturn {\n  message: `\n🔄 <b>Перевод в процессе</b>\n\n📄 Документ: ${$(''Данные document_jobs'').first().json.file_name}\n<b>🗓 Старт:</b> <code>${ startedAt }</code> \n<b>⏱ Прошло: <code>${ diff }</code></b>\n<b>📊 Прогресс:</b> <code>${ `${bar} ${Math.floor(ratio*100)}%` }</code> \n<b>🧩 Текущий чанк: <code>${ done }/${ total }</code></b>\n💰 Потрачено на Polza.ai: \n      ₽ ${ billing_polza.toFixed(2) }\n💰 Потрачено на NeuroAPI: \n      ₽ ${(billing_neuro * RUBLE_EXCHANGE_RATE).toFixed(2).toString().replace(/\\B(?=(\\d{3})+(?!\\d))/g, \" \")}\n\n<i>Сообщение сгенерировано автоматически.</i>\n  `,\n  type: ''edit'',\n  button: {}\n} "}, "typeVersion": 2}, {"id": "6c0a32c7-9cc8-44db-a822-785b3fe9206a", "name": "When Executed by Another Workflow", "type": "n8n-nodes-base.executeWorkflowTrigger", "position": [-1008, 320], "parameters": {"workflowInputs": {"values": [{"name": "qwerty"}]}}, "typeVersion": 1.1}, {"id": "83b54a22-b281-4fff-9ba4-38e2bb0c5ec2", "name": "Редактируем текст сообщения", "type": "n8n-nodes-base.telegram", "position": [-240, 752], "webhookId": "ee3317ee-e386-4133-8122-dcb431c6fcfc", "parameters": {"text": "={{ $json.message }}", "chatId": "={{ $(''Get row(s)'').item.json.chat_id }}", "messageId": "={{ $(''данные по чату'').first().json.message_id }}", "operation": "editMessageText", "addition