INSERT INTO public.workflow_entity VALUES ('[Sub] Billing Check', true, '[{"id": "trigger-billing", "name": "Trigger", "type": "n8n-nodes-base.executeWorkflowTrigger", "position": [-400, 0], "parameters": {"workflowInputs": {"values": [{"name": "job_id", "type": "number"}]}}, "typeVersion": 1.1}, {"id": "billing-polza", "name": "Billing Polza.ai", "type": "n8n-nodes-base.httpRequest", "onError": "continueRegularOutput", "maxTries": 3, "position": [-200, 0], "parameters": {"url": "https://polza.ai/api/v1/balance", "options": {"timeout": 10000}, "sendHeaders": true, "authentication": "genericCredentialType", "genericAuthType": "httpHeaderAuth", "headerParameters": {"parameters": []}}, "credentials": {"httpHeaderAuth": {"id": "3dfmGKUa1Q01H200", "name": "Billing Polza Header"}}, "retryOnFail": true, "typeVersion": 4.4, "alwaysOutputData": true, "waitBetweenTries": 5000}, {"id": "billing-neuro", "name": "Billing Neuro", "type": "n8n-nodes-base.httpRequest", "onError": "continueRegularOutput", "disabled": true, "maxTries": 3, "position": [0, 0], "parameters": {"url": "https://neuroapi.host/v1/dashboard/billing/usage", "options": {"timeout": 10000}, "sendHeaders": true, "authentication": "genericCredentialType", "genericAuthType": "httpHeaderAuth", "headerParameters": {"parameters": []}}, "credentials": {"httpHeaderAuth": {"id": "GIoKsxpIObYHo6Nm", "name": "Billing Neuro Header"}}, "retryOnFail": true, "typeVersion": 4.4, "alwaysOutputData": true, "waitBetweenTries": 5000}, {"id": "save-billing", "name": "Сохранить billing в БД", "type": "n8n-nodes-base.postgres", "position": [200, 0], "parameters": {"query": "=UPDATE document_jobs SET billing_neuro = ''{{ $json.total_usage }}'', billing_polza = ''{{ $json.amount }}'' WHERE id = {{ $(''Trigger'').first().json.job_id }};", "options": {}, "operation": "executeQuery"}, "credentials": {"postgres": {"id": "iGih4QSBWfmpkdGY", "name": "Postgres account"}}, "executeOnce": true, "retryOnFail": true, "typeVersion": 2.6, "alwaysOutp