INSERT INTO public.workflow_entity VALUES ('Переведенный файл в Telegram', true, '[{"parameters":{"operation":"get","dataTableId":{"__rl":true,"value":"select_files","mode":"name"},"returnAll":true},"type":"n8n-nodes-base.dataTable","typeVersion":1.1,"position":[-448,-16],"id":"6b20ca18-75b1-49d9-a07b-95b3f68722f1","name":"Get row(s)","alwaysOutputData":true,"executeOnce":true,"onError":"continueRegularOutput"},{"parameters":{"jsCode":"let text = '''';\nfor (const item of $(''Чанки'').all()) {\n  text += item.json.result_text + ''\\n\\n'';\n}\nconst path = $(''Текущий перевод'').first().json.file_name.replace(/\\.[^/.]+$/, \"\")\nreturn { text, path };"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-288,-16],"id":"11dc1ee0-c9dc-4ae4-abe1-44be9899ba16","name":"Собираем переведенные чанки в единый текст1"},{"parameters":{"operation":"toText","sourceProperty":"text","options":{"encoding":"utf8","fileName":"=translate_{{ $(''Собираем переведенные чанки в единый текст1'').first().json.path }}.txt"}},"type":"n8n-nodes-base.convertToFile","typeVersion":1.1,"position":[-96,-16],"id":"29179bf1-5dbf-4b96-80a9-aae30fc5426e","name":"Convert to File1","executeOnce":true},{"parameters":{"operation":"sendDocument","chatId":"={{ $(''Get row(s)'').first().json.chat_id }}","binaryData":true,"additionalFields":{"fileName":"=translate_{{ $(''Собираем переведенные чанки в единый текст1'').first().json.path }}.txt","parse_mode":"HTML"}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[96,-16],"id":"e2664829-65da-446a-b652-b8721919dbd4","name":"Send a document","webhookId":"edd04996-850a-4287-9493-f929669bdee5","retryOnFail":true,"credentials":{"telegramApi":{"id":"V4jPr27PQcfRRHY9","name":"Telegram account"}}},{"parameters":{"workflowInputs":{"values":[{"name":"job_id","type":"number"}]}},"type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1.1,"position":[-912,-16],"id":"624a6b66-c71b-440b-a327-14c1a27bfa64","name":"Start Workflow"},{"parameters":{"oper