","typeVersion":2,"position":[-368,0],"id":"90983137-c3ee-4a50-ac56-9f8da7f3c844","name":"Имя папки"},{"parameters":{"resource":"folder","name":"={{ $json.folder }}","driveId":{"__rl":true,"mode":"list","value":"My Drive"},"folderId":{"__rl":true,"mode":"list","value":"root","cachedResultName":"/ (Root folder)"},"options":{}},"type":"n8n-nodes-base.googleDrive","typeVersion":3,"position":[-192,0],"id":"167935e8-9de7-4504-947d-969e143d44eb","name":"Create folder","executeOnce":true,"retryOnFail":true,"credentials":{"googleDriveOAuth2Api":{"id":"OfjqR7v8bwrPeQgK","name":"Google Drive account"}}},{"parameters":{"resource":"folder","operation":"share","folderNoRootId":{"__rl":true,"value":"={{ $json.id }}","mode":"id"},"permissionsUi":{"permissionsValues":{"role":"writer","type":"anyone","allowFileDiscovery":true}},"options":{}},"type":"n8n-nodes-base.googleDrive","typeVersion":3,"position":[0,0],"id":"ecee34b9-98fe-4255-98ab-b1f1656b3cc5","name":"Share folder","executeOnce":true,"retryOnFail":true,"credentials":{"googleDriveOAuth2Api":{"id":"OfjqR7v8bwrPeQgK","name":"Google Drive account"}}},{"parameters":{"workflowInputs":{"values":[{"name":"job_id","type":"number"}]}},"type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1.1,"position":[-864,0],"id":"3ea21791-d87a-4c8a-be28-b1c4d63adc6c","name":"Start Workflow"},{"parameters":{"operation":"executeQuery","query":"SELECT \n    * \n  FROM \n    job_current c, \n    document_jobs j \n  WHERE \n    j.id = c.job_id \n  LIMIT 1;","options":{}},"type":"n8n-nodes-base.postgres","typeVersion":2.6,"position":[-704,0],"id":"635ccbc1-de0a-4900-afbb-e445b4142a2f","name":"Текущий перевод","executeOnce":true,"alwaysOutputData":true,"retryOnFail":true,"credentials":{"postgres":{"id":"iGih4QSBWfmpkdGY","name":"Postgres account"}}},{"parameters":{"operation":"executeQuery","query":"SELECT \n    * \n  FROM \n    document_chunks \n  WHERE \n    job_id = {{ $json.job_id }}\n  ORDER BY \n    chunk_index","options":{}},"type":"n8n-no