INSERT INTO public.workflow_entity VALUES ('[Перевод] Арка', true, '[{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"37a0ba6a-bc8c-4d31-812c-f30a9a2bb209","leftValue":"={{ $(''Boundary Arc'').first().json.output.starts_new_arc }}","rightValue":true,"operator":{"type":"boolean","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[48,144],"id":"98f04ff2-e157-4eac-aa9c-d375c87c644f","name":"Нчало новой арки?"},{"parameters":{"numberInputs":3},"type":"n8n-nodes-base.merge","typeVersion":3.2,"position":[1280,128],"id":"11d51c9a-1005-4a8b-86e7-9020cde5b22d","name":"Merge1"},{"parameters":{"operation":"executeQuery","query":"-- Обновим данные о новой арке\nUPDATE \n    document_arcs \n  SET \n    end_chapter = {{ $(''Подготовка данных по главе'').first().json.chapter_number }},\n    summary = ''{{ JSON.stringify($(''Start Summary Arc'').first().json.output).replaceAll(`''`, `''''`) }}'', \n    updated_at = now()\n  WHERE \n    id = {{ $(''Получение данных для арки'').first().json.current_arc }};","options":{}},"type":"n8n-nodes-base.postgres","typeVersion":2.6,"position":[704,496],"id":"a28dffa7-6a19-421c-b2c2-c85e3673f23f","name":"Обновление данных о новой арке","alwaysOutputData":true,"executeOnce":true,"retryOnFail":true,"credentials":{"postgres":{"id":"iGih4QSBWfmpkdGY","name":"Postgres account"}}},{"parameters":{"operation":"executeQuery","query":"-- Добавим причину перехода на новую арку\nUPDATE \n    document_arcs \n  SET \n    reason = ''{{ $(''Boundary Arc'').first().json.output.reason.replaceAll(`''`, `''''`) }}'', \n    updated_at = now() \n  WHERE id={{ $(''Получение данных для арки'').first().json.current_arc }};\n-- Добавим в таблицу с арками новую арку\n-- Обновим в job_current инфу об этой арке\nWITH arc AS (\n  INSERT INTO \n      document_arcs (job_id, arc_number, start_chapter, end_chapter)\n    VALUES \n  