dToMatch":true,"type":"string","removed":false},{"id":"texts","displayName":"texts","required":false,"defaultMatch":false,"display":true,"canBeUsedToMatch":true,"type":"array","removed":true},{"id":"meta_data","displayName":"meta_data","required":false,"defaultMatch":false,"display":true,"canBeUsedToMatch":true,"type":"string","removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":true},"options":{"waitForSubWorkflow":false}},"type":"n8n-nodes-base.executeWorkflow","typeVersion":1.3,"position":[1024,-96],"id":"973c82a1-9903-4f50-993f-4748c4d95aad","name":"Insert into LightRAG","alwaysOutputData":true,"onError":"continueRegularOutput"},{"parameters":{"jsCode":"let input = $(''Получение данных для арки'').first().json.summary\nlet report = \"\";\nif (input == null) return { text: null };\n\n// Форматирование для ГЛАВЫ\n// Форматирование для АРКИ\nreport = `### ТЕКУЩЕЕ СОСТОЯНИЕ АРКИ\\n`;\nreport += `${input.arc_summary_rolling}\\n\\n`;\nreport += `**Основной конфликт:** ${input.main_conflict}\\n`;\nreport += `**Цели героев:** ${input.goals.join(\"; \")}\\n`;\nreport += `**Ключевые изменения:** ${input.key_changes.join(\"; \")}\\n`;\nreport += `**Открытые вопросы:** ${input.open_threads.join(\"; \")}`;\n\nreturn { text: report };\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[608,-16],"id":"eddc07ba-33d6-4b00-8d2c-481358a10209","name":"подготовка текста для LightRAG"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f0402e14-f09f-4b8b-a4c6-8397390519a6","leftValue":"={{ $json.text }}","rightValue":"","operator":{"type":"string","operation":"notEmpty","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[800,-16],"id":"79d0a40a-d311-4eca-bb4c-51a3c3a15208","name":"текст есть?"},{"parameters":{"text":"=CURRENT_ARC_STATE:\n{{ $(''Получение данных для арки'').first().json.summary ? JSON.stringify($(''Получение данных для арки'').first().json.summary) : `Отсутствует` }}\n\nNEW_CHAPTER_SUMMARY:\n{{ JSON.stringify($(''Подготовка данных по главе'').first().json.summary, null, 2) }}","schemaType":"fromJson","jsonSchemaExample":"{ \"starts_new_arc\": true, \"reason\": \"...\" }","options":{"systemPromptTemplate":"Ты — классификатор границы арки в романе.\n\nВход:\n1) ARC_DEFINITION — определение, что мы считаем аркой.\n2) CURRENT_ARC_STATE — текущее состояние арки (главный конфликт/цели/нитки).\n3) NEW_CHAPTER_SUMMARY — summary новой главы.\n\nЗадача:\nВернуть ОДНОЗНАЧНЫЙ ответ: эта глава начинает НОВУЮ арку или продолжает текущую.\n\nARC_DEFINITION (жёстко):\nАрка = непрерывная последовательность глав, объединённых ОДНИМ главным конфликтом/задачей и набором ключевых открытых нитей.\nНовая арка начинается ТОЛЬКО если выполнено хотя бы ОДНО из условий (A–C) и при этом НЕ выполнено условие (D):\n\nA) Главный конфликт текущей арки закрыт или больше не является главным (явно решён/отменён/потерял смысл).\nB) Появился новый главный конфликт/задача, который становится центральным и вытесняет прежний.\nC) Произошёл “перезапуск” ситуации: сменились одновременно (1) основная цель, (2) основной антагонист/сторона конфликта ИЛИ (3) место/сеттинг, и это явно обозначено как начало нового этапа истории.\n\nD) НЕ считать новой аркой:\n- смену локации без смены главного конфликта,\n- флэшбек/вставную сцену, после которой конфликт тот же,\n- временную паузу/передышку,\n- подготовку к следующему шагу в рамках того же конфликта,\n- появление нового персонажа, если конфликт тот же.\n\nПравила вывода:\n- Если ты не видишь условий A–C явно из NEW_CHAPTER_SUMMARY и CURRENT_ARC_STATE — ответ всегда \"продолжается\".\n- Не выдумывай причины и не используй предположения.\n\nТребования к reason:\n- 1–2 коротких предложения, строго факты из CURRENT_ARC_STATE и NEW_CHAPTER_SUMMARY.\n- Никаких предположений/интерпретаций. Запрещены слова: \"возможно\", \"вероятно\", \"кажется\", \"скорее всего\".\n- reason должен ссылаться на критерии ARC_DEFINITION буквами A/B/C/D:\n - если starts_new_arc = true → reason обязан указать, какой критерий сработал (A или B или C) и что именно в данных это подтверждает.\n - если starts_new_arc = false → reason обязан указать, что критерии A–C не подтверждены, либо что сработало исключение D (что это лишь смена локации/флэшбек/передышка/подготовка при том же конфликте).\n- Не повторяй целиком summary, только суть.\n- Переведи на русский язык.\n\nВерни строго JSON без пояснений"}},"type":"@n8n/n8n-nodes-langchain.informationExtractor","typeVersion":1.2,"position":[-432,160],"id":"21e5eb4e-fc39-4dc3-92ec-c47cc7fdca49","name":"Boundary Arc","executeOnce":false,"alwaysOutputData":false,"retryOnFail":true,"onError":"continueErrorOutput"},{"parameters":{"text":"=Текущий rolling summary:\n{{ JSON.stringify($(''Получение данных для арки'').first().json.summary, null, 2) }}\n\nНовый переведённый фрагмент:\n{{ $(''Переведенный чанк'').first().json.result_text }}","schemaType":"fromJson","jsonSchemaExample":"{\n \"arc_summary_rolling\": \"...\",\n \"main_conflict\": \"...\",\n \"goals\": [\"...\"],\n \"key_changes\": [\"...\"],\n \"open_threads\": [\"...\"]\n}\n","options":{"systemPromptTemplate":"Ты обновляешь Rolling Summary текущей арки по итогам новой главы.\nВерни строго JSON формата:\n\nВходные данные:\n1) Текущее rolling summary арки (предыдущее значение).\n2) Summary новой главы (короткое, точное).\n3) (Опционально) список персонажей/терминов.\n\nОБЩИЕ ПРАВИЛА (жёстко):\nA) Используй только факты из входа. Ничего не выдумывай.\nB) Никаких интерпретаций и предположений. Запрещены слова/обороты:\n \"вероятно\", \"возможно\", \"скорее всего\", \"намекается\", \"по-видимому\",\n если в summary главы это не сказано напрямую.\nC) Не добавляй новых деталей мира, не объясняй устройство магии/политики, если этого нет в входе.\nD) Сохраняй максимальную стабильность: если новая глава не меняет пункт/поле — НЕ меняй его.\nE) Избегай синонимов и перефразирований без необходимости. Стабильные формулировки важнее \"красоты\".\nF) Никаких цитат из текста. Только нейтральные факты.\nG) Вывод — только JSON. Никакого дополнительного текста.\n\nКОНТРОЛЬ ДЛИНЫ:\n- arc_summary_rolling: 500–800 символов (строго).\n- main_conflict: 1–2 предложения, до 220 символов.\n- goals: 1–6 пунктов, каждый до 140 символов.\n- key_changes: 0–8 пунктов, каждый до 160 символов.\n- open_threads: 0–8 пунктов, каждый до 160 символов.\n\nСТИЛЬ ФОРМУЛИРОВОК:\n- Пиши в прошедшем времени, короткими фразами.\n- Каждый пункт — одно действие/изменение.\n- Не включай украшательства, эпитеты, оценочную лексику.\n\nСМЫСЛ ПОЛЕЙ (что именно туда кладём):\n\n1) arc_summary_rolling. \nЧто это:\n- Короткая \"сводка арки\" как единый текстовый абзац, который быстро вводит в курс.\n- Должен отвечать на вопросы: \"что за конфликт?\", \"кто основные действующие лица?\",\n \"какие важные события уже случились?\", \"к чему сейчас пришли?\", \"что осталось открытым?\".\n\nДОЛЖНО включать (в таком порядке, 4–6 предложений):\n(1) Описание главного конфликта арки (1 предложение).\n(2) Основные стороны/персонажи/фракции (1 предложение).\n(3) 1–2 ключевых поворотных события (1–2 предложения).\n(4) Текущее состояние/положение дел к последней главе (1 предложение).\n(5)1 предложение про главные открытые линии/риски (если есть).\n(6) Строго на русском языке\n\nНЕ ДОЛЖНО включать:\n- подробный пересказ всех событий по главам,\n- второстепенных персонажей, если они не влияют на конфликт,\n- микродетали сцен.\n\nПравило обновления:\n- Обновляй arc_summary_rolling только если новая глава:\n а) изменила состояние конфликта,\n б) заметно продвинула/изменила цели,\n в) закрыла или открыла важную нитку,\n г) привела к существенным потерям/обретениям.\n\n2) arc_state.main_conflict. \nЧто это:\n- Одна \"главная проблема\" арки, сформулированная максимально конкретно.\n- Это не тема и не мораль, а конфликт/противостояние/задача.\n\nДОЛЖНО:\n- быть одинаковым по смыслу от главы к главе, пока арка не закончилась.\n- включать участников/объект конфликта при наличии (\"герой против X\", \"нужно достичь Y, иначе Z\").\n\nНЕ ДОЛЖНО:\n- менять формулировку ради стиля,\n- становиться слишком общей (\"борьба добра и зла\"),\n- включать догадки о скрытых мотивах.\n\n3) arc_state.goals.\nЧто это:\n- Список текущих явных целей в рамках арки.\n- Цели должны быть измеримыми/проверяемыми (\"найти\", \"достичь\", \"защитить\", \"раскрыть\", \"сбежать\").\n\nДОЛЖНО включать:\n- цели главных действующих лиц (1–3 основных),\n- общие цели группы/фракции, если она важна.\n\nНЕ ДОЛЖНО включать:\n- эмоции (\"хочет быть счастливым\"),\n- общие желания без действий (\"хочет мира\"),\n- цели, которые уже выполнены (если выполнены — переносим в key_changes).\n\nПравила обновления goals:\n- Если цель выполнена → удалить из goals и добавить в key_changes (\"Цель X выполнена\").\n- Если цель изменилась → заменить формулировку, сохранив смысл.\n- Если появилась новая важная цель → добавить1 пункт.\n\n4) arc_state.key_changes.\nЧто это:\n- Ключевые изменения, которые произошли с начала арки до текущего момента.\n- Это \"факты прогресса\": что изменилось в расстановке сил, знаниях, ресурсах, отношениях.\n\nДОЛЖНО включать:\n- получение/потерю важного предмета/ресурса,\n- раскрытие важного факта/личности,\n- смену союза/конфликта,\n- серьёзные травмы/смерти/аресты (если они случились),\n- значимые решения (\"заключили сделку\", \"сбежали\", \"взорвали мост\").\n\nНЕ ДОЛЖНО включать:\n- мелкие события без последствий,\n- повторение уже известных изменений без новой информации.\n\nПравила обновления key_changes:\n- Добавляй только изменения текущей главы, если они \"ключевые\".\n- Не больше1 пункта на одно изменение.\n- Не переписывай старые пункты, если не появилось уточнение.\n\n5) arc_state.open_threads.\nЧто это:\n- Открытые линии, которые ещё не закрыты, и которые важны для арки.\n- Это конкретные \"вопросы/риски/обязательства\".\n\nДОЛЖНО включать:\n- угрозы, которые ещё актуальны,\n- незавершённые расследования,\n- обещания/долги/сроки,\n- \"кто/почему\" загадки, если они реально поставлены.\n\nНЕ ДОЛЖНО включать:\n- вопросы читателя/рецензента,\n- гипотезы без фактов,\n- \"возможные\" будущие события.\n\nПравила обновления open_threads:\n- Если нитка закрыта в новой главе → удалить её и добавить в key_changes (\"Нитка X закрыта/прояснена\").\n- Если нитка стала неактуальной → удалить без замены.\n- Если появилась новая важная нитка → добавить1 пункт.\n\nДЕТЕРМИНИЗМ / ПОВТОРЯЕМОСТЬ:\n- Если новая глава НЕ меняет main_conflict и goals — оставь их без изменений.\n- Изменяй минимум текста в arc_summary_rolling: не переставляй предложения местами без необходимости.\n- Не используй синонимы для ключевых терминов: один термин — одна форма.\n- Сортировка списков:\n goals: по важности (главная цель первой), затем по времени (ближайшая выше).\n open_threads: по срочности/риску.\n key_changes: в хронологическом порядке (самые ранние сверху, новые добавляй в конец)."}},"type":"@n8n/n8n-nodes-langchain.informationExtractor","typeVersion":1.2,"position":[416,160],"id":"c3ac4799-aa1a-4088-bc79-5fc219504183","name":"Rolling Summary Arc","alwaysOutputData":false,"executeOnce":false,"retryOnFail":true,"onError":"continueErrorOutput"},{"parameters":{"text":"=NEW_CHAPTER_SUMMARY:\n{{ JSON.stringify($(''Подготовка данных по главе'').first().json.summary,null,2) }}","schemaType":"fromJson","jsonSchemaExample":"{\n \"arc_summary_rolling\": \"...\",\n \"main_conflict\": \"...\",\n \"goals\": [\"...\"],\n \"key_changes\": [\"...\"],\n \"open_threads\": [\"...\"]\n}","options":{"systemPromptTemplate":"Ты создаёшь стартовое (инициализирующее) Summary новой арки романа.\n\nВход:\n- NEW_CHAPTER_SUMMARY: краткое фактическое summary главы, которая начинает новую арку.\n\nЗадача:\nСоздать \"arc_summary_rolling\" и \"arc_state\" для новой арки ТОЛЬКО на основе NEW_CHAPTER_SUMMARY.\nНичего не выдумывать. Если информации недостаточно — оставляй поле пустым или общим, но без догадок.\n\nЖёсткие правила:\n- Не добавляй фактов, которых нет во входе.\n- Не объясняй мир/мотивы, если это не сказано явно.\n- Формулировки стабильные, нейтральные, без художественных украшений.\n- Сохраняй имена/термины ровно как во входе.\n- Длина arc_summary_rolling: 4–6 предложений, суммарно 700–1200 символов.\n\nСМЫСЛ ПОЛЕЙ (что именно туда кладём):\n\n1) arc_summary_rolling. \nЧто это:\n- Короткая \"сводка арки\" как единый текстовый абзац, который быстро вводит в курс.\n- Должен отвечать на вопросы: \"что за конфликт?\", \"кто основные действующие лица?\",\n \"какие важные события уже случились?\", \"к чему сейчас пришли?\", \"что осталось открытым?\".\n\nДОЛЖНО включать (в таком порядке, 4–6 предложений):\n(1) Описание главного конфликта арки (1 предложение).\n(2) Основные стороны/персонажи/фракции (1 предложение).\n(3) 1–2 ключевых поворотных события (1–2 предложения).\n(4) Текущее состояние/положение дел к последней главе (1 предложение).\n(5) 1 предложение про главные открытые линии/риски (если есть).\n(6) Строго на русском языке\n\nНЕ ДОЛЖНО включать:\n- подробный пересказ всех событий по главам,\n- второстепенных персонажей, если они не влияют на конфликт,\n- микродетали сцен.\n\n2) arc_state.main_conflict. \nЧто это:\n- Одна \"главная проблема\" арки, сформулированная максимально конкретно.\n- Это не тема и не мораль, а конфликт/противостояние/задача.\n\nДОЛЖНО:\n- быть одинаковым по смыслу от главы к главе, пока арка не закончилась.\n- включать участников/объект конфликта при наличии (\"герой против X\", \"нужно достичь Y, иначе Z\").\n\nНЕ ДОЛЖНО:\n- менять формулировку ради стиля,\n- становиться слишком общей (\"борьба добра и зла\"),\n- включать догадки о скрытых мотивах.\n\n3) arc_state.goals.\nЧто это:\n- Список текущих явных целей в рамках арки.\n- Цели должны быть измеримыми/проверяемыми (\"найти\", \"достичь\", \"защитить\", \"раскрыть\", \"сбежать\").\n\nДОЛЖНО включать:\n- цели главных действующих лиц (1–3 основных),\n- общие цели группы/фракции, если она важна.\n\nНЕ ДОЛЖНО включать:\n- эмоции (\"хочет быть счастливым\"),\n- общие желания без действий (\"хочет мира\"),\n- цели, которые уже выполнены (если выполнены — переносим в key_changes).\n\n4) arc_state.key_changes.\nЧто это:\n- Ключевые изменения, которые произошли с начала арки до текущего момента.\n- Это \"факты прогресса\": что изменилось в расстановке сил, знаниях, ресурсах, отношениях.\n\nДОЛЖНО включать:\n- получение/потерю важного предмета/ресурса,\n- раскрытие важного факта/личности,\n- смену союза/конфликта,\n- серьёзные травмы/смерти/аресты (если они случились),\n- значимые решения (\"заключили сделку\", \"сбежали\", \"взорвали мост\").\n\nНЕ ДОЛЖНО включать:\n- мелкие события без последствий,\n- повторение уже известных изменений без новой информации.\n\n5) arc_state.open_threads.\nЧто это:\n- Открытые линии, которые ещё не закрыты, и которые важны для арки.\n- Это конкретные \"вопросы/риски/обязательства\".\n\nДОЛЖНО включать:\n- угрозы, которые ещё актуальны,\n- незавершённые расследования,\n- обещания/долги/сроки,\n- \"кто/почему\" загадки, если они реально поставлены.\n\nНЕ ДОЛЖНО включать:\n- вопросы читателя/рецензента,\n- гипотезы без фактов,\n- \"возможные\" будущие события."}},"type":"@n8n/n8n-nodes-langchain.informationExtractor","typeVersion":1.2,"position":[-256,496],"id":"fbb6cdc0-952f-45a0-bcc1-22d70dec91f0","name":"Start Summary Arc","alwaysOutputData":false,"executeOnce":false,"retryOnFail":true,"onError":"continueErrorOutput"}]', '{"Нчало новой арки?":{"main":[[{"node":"Добавление новой арки","type":"main","index":0}],[{"node":"to log5","type":"main","index":0}]]},"Обновление данных о новой арке":{"main":[[{"node":"Merge1","type":"main","index":2}]]},"Добавление новой арки":{"main":[[{"node":"подготовка текста для LightRAG","type":"main","index":0}]]},"Обновление Suumary арки":{"main":[[{"node":"Merge1","type":"main","index":1}]]},"When Executed by Another Workflow":{"main":[[{"node":"Переведенны