]},"Boundary Arc":{"main":[[{"node":"to log2","type":"main","index":0}],[{"node":"to log7","type":"main","index":0}]]},"Rolling Summary Arc":{"main":[[{"node":"to log6","type":"main","index":0}],[{"node":"to log9","type":"main","index":0}]]},"Start Summary Arc":{"main":[[{"node":"to log4","type":"main","index":0}],[{"node":"to log8","type":"main","index":0}]]}}', '2026-03-06 23:50:39.724+00', '2026-04-28 18:57:55.053+00', '{"timezone":"Europe/Moscow","binaryMode":"separate","callerPolicy":"workflowsFromSameOwner","errorWorkflow":"global-error-handler-36id","timeSavedMode":"fixed","availableInMCP":false,"executionOrder":"v1","saveFailedExecution":"all","saveManualExecutions":true,"saveExecutionProgress":"none","saveDataSuccessExecution":"none"}', NULL, '{"When Executed by Another Workflow":[{"json":{"id_chunk":3487}}]}', '5f6b73c2-3c26-49f6-ba30-58016804c304', 0, 'OggkJgA8IFmasME_BNimq', NULL, 'G9OqDfBu0fq5UT12', false, 362, '', '5f6b73c2-3c26-49f6-ba30-58016804c304');
