_keywords = EXCLUDED.matched_keywords,\n        confidence = EXCLUDED.confidence,\n        matched_at = NOW()\n    RETURNING news_id, instrument_id\n)\nSELECT COUNT(*)::int AS matched_rows FROM upsert_match;","options":{"queryBatching":"independently","queryReplacement":"={{ [$json.source, $json.external_id, $json.secid, $json.matched_keywords] }}","replaceEmptyStrings":true}},"id":"ffff96e5-52e0-4ae4-86bb-4e4d005583b1","name":"Upsert News Match","type":"n8n-nodes-base.postgres","typeVersion":2.6,"position":[1424,144],"credentials":{"postgres":{"id":"HJifIbuLF5vUUVdd","name":"Market Research Postgres RW"}}},{"parameters":{"httpMethod":"POST","path":"moex-news-feed-int-b0e19a6a","options":{"ipWhitelist":"127.0.0.1,::1"}},"id":"20c9a98a-e038-40a8-a94e-353c81df360e","name":"Internal Cron Webhook","type":"n8n-nodes-base.webhook","typeVersion":2.1,"position":[272,128],"webhookId":"4c59a937-f25c-4faf-a6c8-0b93e928a1a7"}]', '{"Get Watchlist":{"main":[[{"node":"Append News And Watchlist","type":"main","index":1}]]},"Append News And Watchlist":{"main":[[{"node":"Match News To Watchlist","type":"main","index":0}]]},"Match News To Watchlist":{"main":[[{"node":"Push News To LightRAG","type":"main","index":0},{"node":"Upsert News Match","type":"main","index":0}]]},"Push News To LightRAG":{"main":[[{"node":"Log News Publish","type":"main","index":0}]]},"Schedule Trigger":{"main":[[{"node":"Read MOEX RSS","type":"main","index":0},{"node":"Get Watchlist","type":"main","index":0}]]},"Read MOEX RSS":{"main":[[{"node":"Prepare Incoming News","type":"main","index":0}]]},"Prepare Incoming News":{"main":[[{"node":"Upsert Raw News Items","type":"main","index":0}]]},"Upsert Raw News Items":{"main":[[{"node":"Keep Fresh News","type":"main","index":0}]]},"Keep Fresh News":{"main":[[{"node":"Append News And Watchlist","type":"main","index":0}]]},"Internal Cron Webhook":{"main":[[{"node":"Read MOEX RSS","type":"main","index":0},{"node":"Get Watchlist","type":"main","index":0}]]}}', '2026-04-17