ибка в процессе","type":"main","index":0}]]},"Сообщение Ошибка в процессе":{"main":[[{"node":"Send message","type":"main","index":0}]]},"Данные document_jobs":{"main":[[{"node":"Get row(s)","type":"main","index":0}]]},"Start Workflow":{"main":[[{"node":"Данные document_jobs","type":"main","index":0}]]}}', '2026-03-29 08:09:39.536+00', '2026-04-09 05:19:58.525+00', '{"binaryMode": "separate", "callerPolicy": "workflowsFromSameOwner", "errorWorkflow": "global-error-handler-36id", "timeSavedMode": "fixed", "availableInMCP": false, "executionOrder": "v1", "saveFailedExecution": "all", "saveManualExecutions": true, "saveExecutionProgress": "none", "saveDataSuccessExecution": "none"}', NULL, '{}', '73a819bd-604c-4798-8364-8231aac3ba31', 0, '2uhp8PCTjxiKj91n', NULL, 'YADn0DLCgXyPQPHF', false, 73, NULL, '73a819bd-604c-4798-8364-8231aac3ba31');
